button.press-feedback {
  box-sizing: border-box;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 8px;
  min-height: 44px;
  min-width: 0;
  padding: var(--pf-padding, 10px 16px);
  border: 1px solid var(--pf-border, transparent);
  border-radius: var(--pf-radius, 8px);
  appearance: none;
  background: var(--pf-background, #18181b);
  color: var(--pf-color, #fff);
  font: inherit;
  line-height: 1.4;
  text-align: center;
  overflow-wrap: anywhere;
  cursor: pointer;
  touch-action: manipulation;
  -webkit-tap-highlight-color: transparent;
}
button.press-feedback:focus-visible {
  outline: 2px solid currentColor;
  outline-offset: 4px;
  outline-color: var(--pf-focus, #52525b);
}
button.press-feedback:disabled {
  opacity: .45;
  cursor: not-allowed;
}
@media (hover: hover) and (pointer: fine) {
  button.press-feedback:enabled:hover {
    background: var(--pf-hover, #3f3f46);
  }
}
@media (prefers-reduced-motion: no-preference) {
  button.press-feedback:enabled:not([data-reduced-motion]):not(:focus-visible) {
    transition: transform var(--pf-duration, 100ms) cubic-bezier(0.23, 1, 0.32, 1);
  }
  button.press-feedback:enabled:not([data-reduced-motion]):not(:focus-visible):active {
    transform: scale(var(--pf-scale, .97));
  }
}

